import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static ArrayList<Integer>[] tree;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // 读入26个字母的个数
        String[] parts = br.readLine().split(" ");
        int[] counts = new int[26];
        for (int i = 0; i < 26; i++) {
            counts[i] = Integer.parseInt(parts[i]);
        }
        n = Integer.parseInt(br.readLine().trim());

        // 初始化树的邻接表
        tree = new ArrayList[n+1];
        for (int i = 1; i <= n; i++) {
            tree[i] = new ArrayList<>();
        }
        for (int i = 1; i <= n-1; i++) {
            String[] edge = br.readLine().split(" ");
            int u = Integer.parseInt(edge[0]);
            int v = Integer.parseInt(edge[1]);
            tree[u].add(v);
            tree[v].add(u);
        }

        // 计算树的直径：使用两次BFS
        int[] firstBFS = bfs(1);
        int u = firstBFS[0]; // 第一次BFS得到的最远点
        int[] secondBFS = bfs(u);
        int diameterEdges = secondBFS[1]; // 边数
        int diameterNodes = diameterEdges + 1; // 结点数

        // 计算能构成的最长回文串长度 L_max
        int evenSum = 0;
        boolean hasOdd = false;
        for (int cnt : counts) {
            evenSum += cnt - (cnt & 1); // 取偶数部分
            if (cnt % 2 == 1) {
                hasOdd = true;
            }
        }
        int L_max = evenSum + (hasOdd ? 1 : 0);

        int ans = Math.min(diameterNodes, L_max);
        System.out.println(ans);
    }

    // BFS返回一个数组：[最远结点, 距离]
    static int[] bfs(int start) {
        boolean[] visited = new boolean[n+1];
        int[] dist = new int[n+1];
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start);
        visited[start] = true;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : tree[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    dist[v] = dist[u] + 1;
                    queue.add(v);
                }
            }
        }
        int maxNode = start, maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] > maxDist) {
                maxDist = dist[i];
                maxNode = i;
            }
        }
        return new int[]{maxNode, maxDist};
    }
}
